import json, csv, re
from pathlib import Path
BASE=Path(__file__).parent
talks=[]; items=[]; problems=[]; corrections=[]
def talk(record,date,speaker,pages,title,summary,kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))
def item(record,pages,kind,title,notes,statement,fate,status,refs=(),cls='E',reconstruction='',literal='correct',match='exact',verification='read the result',development='none',problem='',worth='',confidence='high',speaker=None):
    n=sum(x['record']==record for x in items)+1
    d=dict(id=f'1987-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status='As of 11 November 2026: '+status,literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
    if speaker: d['speaker']=speaker
    items.append(d); return d['id']
def problem(n,title,statement,occurrences,status,refs=()):
    problems.append(dict(id=f'GP-1987-{n:02d}',title=title,statement=statement,occurrences=occurrences,status=status,status_date='2026-11',refs=list(refs)))
def correction(page,place,reads,should,evidence,applies='both',typ='faithful_error'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ))
def save():
    order={t['record']:i for i,t in enumerate(talks)}
    items.sort(key=lambda x:(order[x['record']],int(x['id'].split('.')[-1])))
    for name,value in [('talks',talks),('items',items),('problems',problems)]:
        (BASE/f'middle_{name}.json').write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
    with (BASE/'middle_corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

talk(727,'1987-11-30','Unidentified reporter','P001416','Ruelle zeta functions and transfer determinants',r'The short report names a 1987 paper of D. H. Mayer and records a weighted periodic-orbit zeta function and a quotient of transfer-operator determinants. The date comes from the catalogue heading; the reporter is not identified. The preceding Hecke-character material on the same scan belongs to record 726. Analytic hypotheses needed for Fredholm determinants are absent.')
talk(728,'1987-12-07','Unidentified reporter; intervention by I. M. Gelfand','P001417-P001418','Finite-state dynamical zeta functions and stochastic spectra',r'The speaker proves the rationality of the zeta function of a shift of finite type, then recodes a finite-memory weight as a finite matrix. Gelfand interrupts to distinguish the set of individual stochastic eigenvalues from the set of complete spectra. The latter, explicitly marked as a problem, is the substantive open question developed in this chapter.')
talk(729,'1987-12-07','A. A. Beilinson','P001419-P001422','Adelic string amplitudes, Tamagawa volumes, and epsilon factors',r'Beilinson explains the product formula, the functional equation of the Riemann zeta function, adelic amplitudes attributed to Freund--Witten, and Tamagawa volume calculations. He then moves to Fourier transforms, determinant lines and Laumon\textquotesingle s local epsilon factors. The suggested adelic analogue of moduli-space volumes remains insufficiently specified. The determinant formula must be read with care: its literal sign convention already fails on a constant local system.')
talk(730,'1987-12-07','A. A. Klyachko','P001422-P001424','Equivariant toric bundles and compatible filtrations',r'Klyachko associates decreasing filtrations to invariant divisors of a toric variety and states a compatibility criterion, then asks for cohomology, characteristic classes and classification. Simplicial-complex examples lead to the triangle and tetrahedral boundary. His 1989 paper, submitted in February 1988, supplies the precise smooth and singular compatibility conditions and geometric calculations. The tetrahedral decomposition requires the short-filtration restriction that the notebook omits.')
talk(731,'','-','P001425','Year 1988 heading',r'A year heading only. It has no independent mathematical assertion and no occurrence-index items. The source then places Gelfand\textquotesingle s exercises before Beilinson\textquotesingle s programme, despite the numerical ordering of catalogue records.',kind='heading')
talk(733,'1988-02-08','I. M. Gelfand','P001425','Exercises on determinants, real roots, limits and conformal maps',r'Five elementary questions ask for Cauchy\textquotesingle s determinant, real roots of Rodrigues\textquotesingle polynomial, discontinuities of pointwise limits, and conformal maps of a slit disk and a dumbbell domain. They are exercises in established mathematics. The narrow corridor is specified only pictorially, so a numerical map is not determined by the notes.')
talk(732,'1988-02-08','A. A. Beilinson','P001425','Programme for learning string theory',r'This is an agenda, not a theorem-bearing lecture: two-dimensional conformal theory; operator products; representations of infinite-dimensional Lie algebras; parafermions and \(W\)-algebras; vertex operators; reduction from affine \(\mathfrak{sl}_2\) to Virasoro; moduli; partition and correlation functions; and branching of characters. It gets a talk-list entry but no artificial mathematical items.',kind='plan')
talk(734,'1988-02-08','D. V. Alekseevsky','P001426-P001428','G-structures, first jets, connections and torsion',r'The lecture develops reductions of the frame bundle, their tensor examples and solder forms. First jets of sections become horizontal complements, giving connections and a torsion map. These are standard constructions, not a new existence theorem for canonical connections. The source contains two useful corrections: the principal action is transitive on each fibre, and the vertical tangent quotient belongs to \(P\), not to \(M\).')
talk(735,'1988-02-15','I. M. Gelfand','P001429','Subspace angles and a thermodynamics reading suggestion',r'Gelfand refers to his 1959 exposition of quasilinear equations and asks about two planes in four dimensions and complete invariants of two Hilbert subspaces. The former are principal angles and the latter are described by the theory of two projections. The remarks anticipate the separate problem sheet of 22 February.')
talk(736,'1988-02-15','A. B. Zamolodchikov','P001429-P001434','Conformal field theory and the Virasoro algebra',r'The lecture starts from formal Euclidean correlation functions, operator products and the stress tensor; conservation and tracelessness lead to chiral fields, the stress-tensor OPE and Virasoro modes. Reflection positivity and primary fields are discussed. Several conditions implicit in unitary conformal theory must be restored, and the printed contravariant complex indices reverse the asserted chirality. The broad physical remarks about a smallest length and polyhedra do not determine mathematical theorems.')
talk(737,'1988-02-22','I. M. Gelfand; notes by A. K. Zvonkin','P001435-P001437','Complete invariants called angles: a problem sheet',r'The handout defines an angle to mean a complete orbit invariant, including its attainable values. It passes from Euclidean pairs and configurations under \(GL\), through indefinite quadratic spaces, to a tensor construction and closed Hilbert subspaces. The finite Euclidean and Hilbert questions were already classical; finite indefinite pairs have a later precise canonical-form treatment. An indefinite infinite-dimensional version is too underspecified to classify as an open problem.')
talk(738,'1988-03-21','A. O. Radul','P001438-P001443','Quantum Gelfand--Dikii brackets after Lukyanov',r'Radul reports quantum Miura constructions, preceded by local variational calculus, formal pseudodifferential symbols and the two Gelfand--Dikii brackets. Gelfand interrupts about intrinsic locality, products of local functionals, and a hierarchy based on differentials. Lukyanov\textquotesingle s paper was submitted before this talk and published later in 1988; it proves closure of the quantum algebra. The notebook\textquotesingle s informal hierarchy is not thereby solved. The next heading, Kapranov at P001444, belongs to record 739.')
item(727,'P001416','definition','Weighted periodic-orbit zeta function',r'The notes define \(\zeta_T(z,\varphi)=\exp\sum_{n\ge1}\frac{z^n}{n}\sum_{\xi\in\operatorname{Fix}T^n}\prod_{k=0}^{n-1}\varphi(T^kx)\).',r'If every fixed-point set is finite, the same formula with \(x=\xi\) defines a formal series. It defines a holomorphic germ when its weighted fixed-point sums grow at most exponentially. The product contains exactly \(n\) factors.',r'The bibliographical pointer is \citet[abstract, pp.~105--115]{mayer1987location}, published in August 1987 before this report; it places the definition in an already established thermodynamic-formalism setting. The reporter is not identified as Mayer.','The weighted periodic-orbit definition is established; analytic continuation depends on the dynamical and function-space hypotheses, and does not follow merely from the displayed formal series.',refs=['mayer1987location'],literal='correct with missing hypotheses',verification='publisher metadata checked',reconstruction=r'The bound for convergence and the correction of the dummy variable are explicit additions. No global continuation is claimed from the definition alone.')
item(727,'P001416','theorem','A quotient of transfer-operator Fredholm determinants',r'For a full-branch piecewise linear interval map the notes write \(\zeta_T=\det(1-zL_1)/\det(1-zL_2)\), with \(L_1f=\varphi\sum_j\rho_j^{-1}f\circ\psi_j\) and \(L_2f=\varphi\sum_jf\circ\psi_j\).',r'One precise version assumes finitely many holomorphic contracting inverse branches \(\psi_j\) on a complex domain, holomorphic weights, and a holomorphic function space on which the induced operators are nuclear and satisfy the fixed-point trace formula. Put \(L_1f(w)=\sum_j\psi_j\prime(w)\varphi(w)f(\psi_jw)\), \(L_2f(w)=\sum_j\varphi(w)f(\psi_jw)\). For affine branches, subtraction of the two fixed-point traces gives the weighted periodic-orbit sum, hence the displayed determinant quotient near zero and by continuation. Periodic endpoint multiplicities must follow the chosen coding.',r'\citet[abstract]{mayer1987location} explicitly uses nuclear operators on holomorphic Banach spaces. Only that abstract and metadata were read; the precise model stated here is a reconstruction using the trace identity, not a claim that every hypothesis was read in Mayer\textquotesingle s text.','Established in analytic transfer-operator settings. The unrestricted interval-map statement is incomplete, and the title about pole location is not enough evidence for a theorem that all poles are real.',refs=['mayer1987location'],literal='correct with missing hypotheses',match='partial',verification='publisher metadata checked',confidence='medium',reconstruction=r'The analytic setting, signed derivative \(\psi_j\prime\), and boundary convention are supplied. Keeping \(\varphi(w)\) outside the sum is compatible with the cyclic product along periodic orbits. A pole-location theorem itself is not stated in the notebook.')
correction('P001416','weighted zeta definition, last display',r'\prod_{k=0}^{n-1}\varphi(T^k x) with sum over \xi',r'\prod_{k=0}^{n-1}\varphi(T^k\xi)','Scan inspected: the notebook itself has x while the outer summation variable is xi. Dummy-variable emendation, not a mistranscription.')
correction('P001416','Mayer attribution','Lindon Mayer (?)','D. H. Mayer (bibliographic identification; retain uncertainty about the reporter)','The scan has a doubtful name; the exact title, journal volume 14 and year match the opened Springer article by Dieter H. Mayer.','both','provenance')

item(728,'P001417','construction','Finite-type shift and periodic-point counts',r'The alphabet \(F\), allowed neighbour pairs \(M\subset F\times F\), bi-infinite admissible sequences and the shift \(T\) are defined. The adjacency operator is then introduced.',r'For the zero-one adjacency matrix \(A\) of a finite directed graph, the two-sided edge-admissible shift has \(N_n=\#\operatorname{Fix}(T^n)=\operatorname{tr}(A^n)\). The trace counts closed walks with a distinguished starting position, exactly as fixed sequences are counted.',r'This is the finite-matrix part of the dynamical-zeta theory already underlying the references of \citet{mayer1987location}. Its proof is the elementary closed-walk count written in the notes.','The count is exact for finite alphabets; no mixing, irreducibility, or aperiodicity is needed.',refs=['mayer1987location'],verification='publisher metadata checked')
item(728,'P001417','theorem','Rationality of the zeta function of a finite-state shift',r'The speaker derives \(\zeta_T(s)=\det(1-sA)^{-1}\) from \(N_n=\operatorname{tr}A^n\), initially for \(|s|<1/\#F\).',r'For every finite square matrix \(A\), \(\exp(\sum_{n\ge1}\operatorname{tr}(A^n)s^n/n)=\det(I-sA)^{-1}\) as a formal series, hence as analytic germs. For a zero-one \(m\)-state shift, \(|s|<1/m\) is a sufficient convergence disk; the rational expression continues meromorphically to the whole complex plane.',r'The source itself supplies the trace-log argument; the finite-state case predates the analytic-transfer work cited in \citet{mayer1987location}.','Completely settled; the convergence bound in the notebook need not be optimal.',refs=['mayer1987location'],verification='publisher metadata checked')
item(728,'P001418','remark','Single-eigenvalue constraints for a stochastic matrix',r'Gelfand recalls that a stochastic matrix has eigenvalue \(1\) and spectrum in the unit disk, and mentions work of Dynkin and Dmitriev on the possible position of an individual eigenvalue.',r'For a real row-stochastic \(n\times n\) matrix \(P\), \(P\mathbf1=\mathbf1\) and \(\rho(P)\le\|P\|_\infty=1\); nonreal eigenvalues occur in conjugate pairs. Determining the union of possible individual eigenvalues projects away all correlations between eigenvalues and is a different question from realizing a whole multiset.',r'The elementary bound follows directly from the stated stochastic hypotheses. The exact single-eigenvalue region was determined by \citet{karpelevich1951roots}; its opened record confirms publication in1951, received19May1950. The source attribution to Dynkin and Dmitriev concerns earlier work and is retained. The joint problem is assessed separately in item1987-728.4.','These elementary necessary conditions are known and are far from a sufficient joint-spectrum criterion.',refs=['karpelevich1951roots'],verification='publisher metadata checked',match='partial',speaker='I. M. Gelfand')
item(728,'P001418','problem','All eigenvalues of a stochastic matrix simultaneously',r'Gelfand expressly asks for the region of complete eigenvalue lists in \(\mathbb C^n\), emphasizing that the known plane region describes only its projection. The Russian marks this \ru{Задача!!}.',r'For each fixed \(n\), characterize the multisets \(\Lambda=(1,\lambda_2,\ldots,\lambda_n)\) for which a real matrix \(P\ge0\), \(P\mathbf1=\mathbf1\), has characteristic polynomial \(\prod_{j=1}^n(t-\lambda_j)\). Multiplicity is algebraic; reducible and non-diagonalizable matrices are allowed. No doubly stochastic, symmetry or prescribed-zero-pattern condition is imposed.',r'This is the stochastic inverse eigenvalue problem, rather than the one-eigenvalue region. The chapter\textquotesingle s development and its exact literature comparison give low-dimensional realizations, necessary moment inequalities and the unresolved general obstruction.','The general fixed-size joint realization problem remains only partially characterized. The chapter settles the stated low-dimensional subcases, without claiming a criterion for arbitrary lists or arbitrary n.',cls='C',refs=[],verification='indirect',match='partial',development='developed in this chapter',problem='GP-1987-21',worth='A bounded development is worthwhile because exact small-dimensional realizations and explicit moment obstructions sharpen the distinction the notes make between a spectral projection and a full spectrum.',speaker='I. M. Gelfand')
problem(21,'Joint spectra of row-stochastic matrices',r'For each \(n\), give necessary and sufficient conditions on a complex multiset \((1,\lambda_2,\ldots,\lambda_n)\) to be the spectrum of a real nonnegative \(n\times n\) matrix with every row sum equal to one.',['1987-728.4'],'2026-11: partially solved in general; the chapter gives exact low-dimensional cases and necessary moment inequalities. The one-eigenvalue region is not a solution of the simultaneous realization problem.')
item(728,'P001418','theorem','Finite-memory weights reduce to a finite matrix',r'The speaker replaces the alphabet by admissible blocks of length \(k\), gives the overlap transition rule, and obtains \(\zeta_T(s,\varphi)=\det(I-sL)^{-1}\). The orbit product in this page is printed with upper limit \(n\).',r'If \(\varphi\) depends on \(k\) consecutive symbols, let \(L_{\alpha\beta}=\varphi(\alpha)\) when the admissible blocks overlap and concatenate, and zero otherwise. Then \(\operatorname{tr}L^n\) is the sum of \(\prod_{j=0}^{n-1}\varphi(T^jx)\) over period-n fixed sequences, and the weighted zeta function is \(\det(I-sL)^{-1}\).',r'This is the same finite-dimensional trace-log identity as item 1987-728.2, applied to the higher-block presentation; it is expository material in the transfer-operator setting of \citet{mayer1987location}.',r'The corrected finite-memory theorem is exact. The literal product of n+1 weights is false: for a one-symbol shift of constant weight c it gives \((1-sc)^{-c}\), rather than \((1-sc)^{-1}\).',refs=['mayer1987location'],literal='false as written',verification='publisher metadata checked',reconstruction=r'The upper bound is corrected from n to n-1, as required by the stated transition matrix; no arbitrary long-range potential is covered.',development='annotated')
correction('P001418','weighted zeta, equation (5)',r'\prod_{k=0}^{n}\varphi(T^k x)',r'\prod_{k=0}^{n-1}\varphi(T^k x)','Scan inspected: n is in the notebook. A one-symbol shift with weight c falsifies the determinant identity with n+1 factors; this is an emendation of the mathematical formula.')
save()
item(730,'P001422-P001423','definition','Toric varieties, fans, and equivariant vector bundles',r'The speaker defines a toric variety by an algebraic-torus action with an orbit isomorphic to the torus, associates a fan, and defines a compatible linear action on a vector bundle.',r'A normal toric variety over an algebraically closed field contains \(T\simeq(\mathbb G_m)^d\) as a dense open orbit, with multiplication extending to the variety. It corresponds to a rational polyhedral fan in \(N_\mathbb R\), where \(N=\operatorname{Hom}(\mathbb G_m,T)\) is the cocharacter lattice. A toric vector bundle is an algebraic vector bundle equipped with a T-action linear on fibres and covering the base action.',r'This is the standard background recalled by \citet[Section~1]{klyachko1989equivariant}. The existence of an orbit merely isomorphic to T is not enough without density and normality.','Established definitions. The combinatorial lattice belongs to one-parameter subgroups, not an arbitrary vector-space identification with the Lie algebra.',refs=['klyachko1989equivariant'],literal='correct with missing hypotheses',reconstruction='Density, normality and the integral cocharacter structure are supplied.')
item(730,'P001423','theorem','Klyachko classification by compatible filtrations',r'An equivariant bundle yields a vector space E and decreasing filtrations \(E^\alpha(i)\), one for each ray. The notes require the subspaces on each cone to generate a distributive lattice.',r'On a smooth toric variety \(X_\Sigma\), toric vector bundles correspond to finite-dimensional E with exhaustive separated decreasing integer filtrations \(E^\rho(i)\). On every cone \(\sigma\) there must be a decomposition \(E=\bigoplus_{u\in M}E_u\) with \(E^\rho(i)=\sum_{\langle u,v_\rho\rangle\ge i}E_u\) for all rays of that cone. Morphisms preserve every filtration. On a smooth cone simultaneous splitting, equivalently distributivity, supplies such integral characters. For singular cones the integral-character compatibility must be imposed explicitly.',r'\citet[Theorems~0.1.1 and 2.2.1]{klyachko1989equivariant} gives the precise equivalence. The paper was received on 3 February 1988, published in Russian in 1989 and translated in 1990; the seminar documents circulation in December 1987.','The theorem is established, including a precise singular version. The raw distributivity criterion without smoothness is incomplete.',refs=['klyachko1989equivariant'],cls='A',literal='correct with missing hypotheses',reconstruction='The smooth/singular distinction, finite filtration conditions, character lattice, and morphisms are supplied from the identified theorem.')
item(730,'P001423','problem','Recover cohomology and characteristic classes from filtrations',r'The explicit tasks are to compute cohomology, Chern classes and related geometric quantities from the filtration data.',r'Given a smooth complete toric variety with fan \(\Sigma\) and a compatible filtered vector space representing \(\mathcal E\), determine the weight spaces of \(H^q(X_\Sigma,\mathcal E)\) and the Chern classes from that finite combinatorial data. Completeness ensures finite-dimensional global cohomology; for a noncomplete variety the characterwise construction still needs the corresponding finiteness interpretation.',r'\citet[Theorems~3.2.1, 4.1.1 and 4.2.1]{klyachko1989equivariant} gives Chern-class formulas, a complex computing cohomology and character formulas. Submission February 1988 followed this December 1987 report; publication was 1989/1990.',r'The stated recovery problem is solved by Klyachko\textquotesingle s constructions. This is not an unsolved request for a new cohomology theory.',refs=['klyachko1989equivariant'],cls='A',literal='correct with missing hypotheses',problem='GP-1987-22',reconstruction='Completeness and the precise output invariants are added to make the question finite and testable.')
problem(22,'Geometric invariants of equivariant toric bundles from filtrations',r'Compute cohomology, weight characters and Chern classes of an equivariant vector bundle on a smooth complete toric variety directly from its compatible ray filtrations.',['1987-730.3'],r'2026-11: solved in Klyachko\textquotesingle s 1989 paper (English translation 1990), Theorems3.2.1,4.1.1,4.2.1.',['klyachko1989equivariant'])
item(730,'P001423','problem','Classification and moduli of compatible filtration data',r'The second broad task is classification of the bundles; the speaker then abstracts the compatibility rule to a finite simplicial complex with a filtration at every vertex.',r'For a fixed complex K, a fixed rank r and prescribed dimensions of the filtration steps, classify the configurations of flags in \(\mathbb C^r\) whose subspaces are simultaneously split on each simplex, modulo simultaneous \(GL_r\). For a toric fan, use the stronger character compatibility when needed. Constructing a parameter space and understanding its orbit equivalence is a precise interpretation of classification; it need not produce a finite list.',r'For toric bundles, \citet[Theorem~1.1 and Section~4]{payne2008moduli}, first circulated in May 2007 and published in 2008, constructs framed moduli with fixed equivariant Chern data and proves Murphy\textquotesingle s law already in rank three. This develops the geometric moduli question, while not claiming a simple orbit list for every abstract simplicial complex.','Established moduli constructions and severe singularity phenomena explain the limits of a uniform elementary classification. The arbitrary-complex reformulation remains a representation problem with complexity depending on K, not one unqualified open conjecture.',refs=['payne2008moduli','klyachko1989equivariant'],cls='B',literal='correct with missing hypotheses',match='partial',problem='GP-1987-23',reconstruction='Rank, flag dimensions and the quotient problem are supplied; the paper cited solves the toric fixed-data moduli problem, not every possible meaning of classification.')
problem(23,'Moduli of compatible filtrations and toric bundles',r'For fixed fan, rank and equivariant Chern data, construct and analyze the moduli of compatible ray filtrations modulo change of basis; distinguish this from a finite indecomposable list for an arbitrary simplicial complex.',['1987-730.4'],r'2026-11: toric fixed-data moduli spaces are constructed; rank-three examples satisfy Murphy\textquotesingle s law (Payne2008). This supplies a moduli formulation, with no assertion of finite-type representation classification for every complex.',['payne2008moduli','klyachko1989equivariant'])
item(730,'P001423','theorem','A filled simplex has only one-dimensional split summands',r'For the triangle, all three filtrations are compatible and the speaker decomposes the representation into one-dimensional ones.',r'If all filtrations attached to the vertices of a filled simplex are simultaneously split, choose a common basis of E adapted to every filtration. The one-dimensional coordinate lines, endowed with their integer jump positions, give a direct-sum decomposition of the filtered object. This uses a filled simplex; its boundary has weaker compatibility.',r'This is the elementary simultaneous-basis content of the distributivity condition in \citet[Theorem~0.1.1]{klyachko1989equivariant}; no later classification is needed.','The splitting is exact for the stated common-basis condition. It must not be transferred to complexes where only proper faces are constrained.',refs=['klyachko1989equivariant'],reconstruction='The distinction between a filled triangle and its boundary is made explicit.')
item(730,'P001423-P001424','claim','Tetrahedral configurations and the short-filtration restriction',r'For the boundary of a tetrahedron the notes give four planes in general position in a three-dimensional space, their exterior powers, and assert that all representations split into those and one-dimensional objects.',r'The matching theorem concerns toric bundles on projective space whose ray filtrations are short: each has at most one proper nonzero subspace, with allowed integer shifts. For \(\mathbb P^3\), such bundles decompose into line bundles and the appropriate twists of exterior powers of its cotangent bundle. Their filtration configurations include the four general-position planes described in the notes. The same conclusion for arbitrary long filtrations does not follow.',r'\citet[Theorem~6.4.1]{klyachko1989equivariant} states the required short-filtration theorem; published1989/1990 after its December1987 exposition. The missing restriction is substantive.','The restricted theorem is established. The unqualified notebook sentence is not a classification of all vector bundles on projective three-space or of all arbitrary-length tetrahedral flag configurations.',refs=['klyachko1989equivariant'],cls='A',literal='correct with missing hypotheses',match='partial',reconstruction='The short-filtration hypothesis is taken from the proved theorem. The source does not state it explicitly, so the literal unrestricted assertion is not endorsed.')
item(730,'P001424','remark','Isolating tractable pieces of a representation problem',r'Gelfand urges finding the solvable portions of any classification problem and refers to the ideology of Gelfand--Ponomarev.',r'The supported content is a methodological recommendation: split direct-sum objects into indecomposables and identify representation-finite or otherwise tractable subclasses before seeking a uniform description. It is not a claim that every classification problem has a computable finite list.',r'The concrete antecedent is \citet{gelfandponomarev1971quadruples}, already discussed in the earlier index at 1970-198 and 1972-277; the present sheet later explicitly returns to the four-subspace problem.','A documented methodological link, with no new unsolved mathematical assertion.',refs=['gelfandponomarev1971quadruples'],match='thematic only',verification='publisher metadata checked',speaker='I. M. Gelfand')
item(730,'P001424','theorem','Kac: indecomposable dimension vectors are positive roots',r'The notes connect dimensions at graph vertices to coordinates of roots of a Kac--Moody algebra, mention numbers of parameters, and cite Lecture Notes996 and an earlier Inventiones paper.',r'For a finite quiver without loops over an algebraically closed field, the dimension vectors of indecomposable representations are exactly the positive roots of the associated symmetric Kac--Moody root system. A positive real root gives a unique indecomposable up to isomorphism. For imaginary roots there can be parameter families; a bare dimension vector does not specify a unique object. The Tits quadratic form controls the parameter count in the precise representation-variety formulation.',r'The exact volume cited is \citet[pp.~74--108]{kac1983roots}, published in1983 and listed on Kac\textquotesingle s own bibliography. The linked scan was too large to read here; verification is limited to identification and metadata.',r'Kac\textquotesingle s root theorem is established and predates the talk. It classifies dimension vectors and real-root objects, not every imaginary-root isomorphism class by a single root.',refs=['kac1983roots'],literal='correct with missing hypotheses',verification='publisher metadata checked',reconstruction='The field, quiver and real-versus-imaginary hypotheses are supplied, and no unverified universal moduli-dimension formula is substituted for the shorthand.')
correction('P001423','filtration equivalence','Distributivity on every cone, with no smoothness condition','For smooth toric varieties this is sufficient; for a singular cone impose an integral character decomposition','Klyachko Theorems0.1.1 and2.2.1, full English paper read. The scan states the short condition without this distinction.','both','ambiguity')
correction('P001424','tetrahedral decomposition claim','An arbitrary representation decomposes into one-dimensional objects and the indicated exterior powers','State the short-filtration restriction of Klyachko Theorem6.4.1','The source scan has an unrestricted assertion; the matching published theorem explicitly restricts filtration length. A mathematical qualification, not a transcription correction.','both','ambiguity')
save()
item(729,'P001419','theorem','The rational product formula and p-adic arithmetic',r'After Gelfand urges the audience to learn p-adic arithmetic and root extraction, Beilinson writes \(\prod_v|a|_v=1\), with \(a\in\mathbb Q\), and checks \(a=1/2\).',r'For \(a\in\mathbb Q^\times\), normalize \(|p|_p=p^{-1}\) and take the usual real absolute value. Then \(|a|_\infty\prod_p|a|_p=1\), with only finitely many nonunit factors. Learning root extraction means solving equations when solutions exist; it does not assert that \(\mathbb Q_p\) is algebraically closed.',r'The product formula and the adelic measure framework are classical; \citet[Chapters~I--II]{serre1981adeles} predates the talk. The displayed example follows immediately from the valuation of 2.','The theorem is exact after excluding a=0. No new assertion that arbitrary p-adic elements admit every root is attributed to Gelfand.',refs=['serre1981adeles'],literal='correct with missing hypotheses',verification='publisher metadata checked',reconstruction='The nonzero hypothesis and normalization are supplied.')
item(729,'P001419','theorem','Completed zeta functional equation and a wrong power of pi',r'Equation (2) is the completed Riemann zeta functional equation. Equation (3) rewrites it with a factor \(\pi^{1-s}\) and an Euler product, explicitly saying analytic continuation is understood.',r'With \(\Lambda(s)=\pi^{-s/2}\Gamma(s/2)\zeta(s)\), one has \(\Lambda(s)=\Lambda(1-s)\) meromorphically. Consequently \(\zeta(1-s)/\zeta(s)=\pi^{1/2-s}\Gamma(s/2)/\Gamma((1-s)/2)\), wherever the quotient is defined and then by meromorphic continuation. The formal product \(\prod_p(1-p^{-s})/(1-p^{s-1})\) is not a pair of ordinarily convergent Euler products on any common half-plane.',r'\citet[25.4.3--25.4.4]{nist2026dlmf} gives the established symmetric equation. The notes\textquotesingle exponent follows neither from it nor from a change of gamma convention.','The equation is classical; the exponent 1-s is a faithful notebook error and must be 1/2-s. Analytic continuation, explicitly mentioned in the source, remains essential.',refs=['nist2026dlmf'],literal='false as written',reconstruction=r'The gamma ratio is corrected by direct division of equation (2).',development='annotated')
item(729,'P001419','claim','Adelic factorization of string amplitudes',r'The gamma ratio is described as approximately an open-string Veneziano--Witten amplitude, with a product over primes. Three recent papers are named: Volovich, Manin, and Witten with an unnamed coauthor.',r'The identifiable reference is Freund--Witten\textquotesingle s factorization of appropriate four-particle open- and closed-string amplitudes into p-adic factors, after analytic continuation and normalization. The single-variable gamma ratio displayed here is an illustrative specialization; it does not specify the full three Mandelstam variables, on-shell constraint, or normalization of a complete amplitude.',r'\citet[abstract]{freundwitten1987adelic} identifies the missing coauthor and states the Veneziano and Virasoro--Shapiro product relations. Journal publication was 17 December 1987, ten days after the seminar; the report itself is evidence of earlier circulation. Only metadata and abstract were read.',r'The particular paper is identified with high confidence. The notebook\textquotesingle s schematic one-variable expression is only a partial match to its complete amplitude formulas.',refs=['freundwitten1987adelic'],cls='B',literal='correct with missing hypotheses',match='partial',verification='publisher metadata checked',reconstruction='The amplitude identification comes from the named topic and opened abstract; no missing multivariable formula is attributed to the speaker.')
item(729,'P001420','theorem','Tamagawa volume of SL(n) and the real lattice covolume',r'The shorthand \ru{Мера Тамагавы = 1} is expanded into \(\operatorname{vol}(SL_n(\mathbb A)/SL_n(\mathbb Q))=1\) and \(\operatorname{vol}(SL_n(\mathbb R)/SL_n(\mathbb Z))=\prod_{j=2}^n\zeta(j)\).',r'For \(n\ge2\), use the restricted adelic product and Tamagawa Haar measures from a rational invariant top form. Then \(\tau(SL_n)=1\). With compatible real and p-adic normalization and \(\operatorname{vol}(SL_n(\mathbb Z_p))=\prod_{j=2}^n(1-p^{-j})\), strong approximation gives the stated real covolume. Replacing Haar measure by an arbitrary scalar multiple changes that covolume.',r'These are classical volume calculations; \citet[Chapters~II--III, especially the contents at pp.~122 and 180]{serre1981adeles} records the relevant pre-1987 framework. Full scan access exceeded the reader limit, so verification is metadata, not a claim to have read its proof.','The normalized theorem is settled. The statement concerns the volume of an arithmetic quotient, not the total measure of the group or an unnormalized Haar measure.',refs=['serre1981adeles'],literal='correct with missing hypotheses',verification='publisher metadata checked',reconstruction='The restricted product, quotient, and common normalization are made explicit.')
item(729,'P001420','construction','The SL(2) volume picture on the hyperbolic plane',r'The notes identify \(SL_2(\mathbb R)\) with disk automorphisms and use hyperbolic area times an angular measure on \(S^*H^2\).',r'Orientation-preserving hyperbolic-plane isometries form \(PSL_2(\mathbb R)=SL_2(\mathbb R)/\{\pm I\}\); they act simply transitively on oriented unit tangent frames. Hyperbolic area times fibre-angle measure is Haar measure on this frame group. Lifting it to \(SL_2\) requires accounting for the double cover before comparing with the Tamagawa normalization.',r'The construction is classical and illustrates the arithmetic-volume calculation of item 1987-729.4; see the real-measure and arithmetic-group sections listed in \citet{serre1981adeles}.','The geometric model is valid after distinguishing SL from PSL and fixing the angular period. It alone does not select the normalization giving zeta(2).',refs=['serre1981adeles'],literal='correct with missing hypotheses',match='partial',verification='publisher metadata checked',reconstruction='The central quotient and double-cover normalization are supplied.')
item(729,'P001420-P001421','theorem','Counting GL(n) and SL(n) over a finite field',r'The audience is asked to count \(SL_n(\mathbb F_p)\); the next page counts successively independent columns of \(GL_n\) and divides by \(p-1\).',r'For a prime power \(q\), \(\#GL_n(\mathbb F_q)=\prod_{i=0}^{n-1}(q^n-q^i)\), because each new column must avoid the span of its predecessors. The surjective determinant map has equally sized fibres, so \(\#SL_n=\#GL_n/(q-1)=q^{n^2-1}\prod_{j=2}^n(1-q^{-j})\).',r'The argument is fully present in the source and belongs to the classical-group point counts listed at p.~20 of \citet{serre1981adeles}.','The formula is exact, including n=1 with the empty product. It supplies the local factors used in the previous volume formula.',refs=['serre1981adeles'],verification='publisher metadata checked')
item(729,'P001421','question','An adelic volume analogy for moduli of curves',r'Manin is credited with an analogous formula for a moduli-space volume; Gelfand asks what p-adic volume and an adelic Teichmuller space would mean.',r'No precise moduli functor, genus, marked-point data, differential form or measure normalization, convergence condition, or equation is given. The strongest supported content is a request to formulate an adelic analogue of the preceding volume comparison.',r'Searches for Manin\textquotesingle s arithmetical-physics reflections identify a contemporaneous programme, but neither the notebook nor the accessible bibliographic records supplies an exact conjecture to match. The explicit amplitude relation of \citet{freundwitten1987adelic} concerns a different, specified object.','No definite statement can be assigned a solved or open status from these notes. Later p-adic moduli and string constructions do not by themselves identify this particular question.',refs=['freundwitten1987adelic'],cls='F',literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low')
item(729,'P001421','method','Fourier transformation moves local information to infinity',r'A compactly supported generalized function on the line is Fourier transformed to a smooth function; the notes say its singularities become asymptotic behaviour at infinity, then mention Laumon\textquotesingle s use of Witten\textquotesingle s Morse-theoretic ideas.',r'For \(u\in\mathcal E\prime(\mathbb R)\), \(\widehat u(z)=\langle u(x),e^{-izx}\rangle\) is entire of exponential type and of polynomial growth on the real axis. Smoothness and singular support are reflected in directional decay of localized Fourier transforms. A single unspecified asymptotic expansion need not determine every singularity; the full Fourier transform determines u.',r'\citet[Introduction, pp.~131--134]{laumon1987fourier} explicitly develops the finite-field Fourier analogy and acknowledges Witten\textquotesingle s Morse-theory inspiration. The real-distribution statement is standard background, not a theorem first proved there.',r'The real Fourier statement is established. Laumon\textquotesingle s arithmetic stationary-phase construction is a precise analogue, not an identification of real distributions with l-adic sheaves.',refs=['laumon1987fourier'],literal='correct with missing hypotheses',match='partial',reconstruction='The entire extension and localized decay formulation clarify the informal word singularities; they are not asserted to be verbatim in the notes.')
item(729,'P001421-P001422','construction','Determinant line of a finite complex',r'The notes set \(\det H^\bullet=(\det H^0\otimes\det H^2)\otimes(\det H^1)^{-1}\) and assert equality with the analogous determinant of a complex.',r'For a bounded complex \(C^\bullet\) of finite-dimensional vector spaces, define \(\det C^\bullet=\bigotimes_i(\bigwedge^{\dim C^i}C^i)^{(-1)^i}\). The short exact sequences of boundaries, cycles and cohomology give a natural isomorphism \(\det C^\bullet\simeq\det H^\bullet(C)\), with coherent graded signs. Finiteness or a perfect-complex hypothesis is necessary.',r'The construction was established before the talk in \citet[Section~I]{knudsenmumford1976det}; the opened author-hosted scan confirms the publication, while the exact finite-dimensional isomorphism is also obtained directly from the two short exact sequences.','Standard determinant-functor theory. This valid isomorphism must be separated from the following divisor formula, whose displayed sign is inconsistent.',refs=['knudsenmumford1976det'],literal='correct with missing hypotheses',verification='publisher metadata checked',reconstruction='The boundedness, finite-dimensionality and graded-sign conditions are supplied.')
item(729,'P001422','claim','The determinant-divisor formula has the wrong variance',r'For \(D=\sum a_ix_i\), the notes define \(\det F_D=\bigotimes_i(\det F_{x_i})^{a_i}\), then write \(\det H^\bullet(X,F)=\det F_K\) for the canonical divisor K.',r'The divisor construction is meaningful for a local system F and a specified divisor. The claimed natural identity with K is false under the immediately preceding alternating determinant convention. For a constant local system V on a compact genus-g curve, automorphisms of V act on \(\det R\Gamma(X,V)\) with determinant weight \(2-2g\), while \(\det V_K\) has weight \(2g-2\). Dualizing the right side removes this elementary sign obstruction, but a canonical general product formula requires additional local epsilon data and conventions.',r'\citet[Section~I]{knudsenmumford1976det} fixes the determinant convention; \citet[Chapter~III, Theorem~3.2.1.1]{laumon1987fourier} proves a precise arithmetic epsilon-product statement, not this unqualified identity of lines.','The literal formula is false functorially. The sign diagnosis is decisive even on a constant sheaf on the projective line; it does not establish a replacement theorem for arbitrary constructible sheaves.',refs=['knudsenmumford1976det','laumon1987fourier'],literal='false as written',match='partial',development='annotated',reconstruction=r'The comparison of determinant weights is our consistency check. We do not silently replace the source formula by an asserted canonical isomorphism with \(F_{-K}\).')
item(729,'P001422','theorem','Laumon: local factors for global epsilon constants',r'The discussion of determinants is presented as a report on Laumon\textquotesingle s work in number theory and on a local description of the functional-equation constant.',r'For a smooth proper curve over a finite field of characteristic p and a constructible l-adic complex, \(l\ne p\), the global epsilon constant of its L-function is expressed as a product of locally defined epsilon factors, with the normalization and genus/rank factor specified by Laumon. A nonzero rational differential supplies the local additive characters; the resulting global expression is independent of that choice. Local Fourier transforms and stationary phase supply the proof.',r'\citet[Theorem~3.2.1.1; Remark~3.2.1.3]{laumon1987fourier} contains the exact product theorem. It was already published in 1987 when Beilinson reported it in December.','Established. The field, coefficient and normalization hypotheses matter: this result cannot be read as a blanket complex-analytic determinant-line formula.',refs=['laumon1987fourier'],literal='correct with missing hypotheses',match='partial',reconstruction='The arithmetic objects and hypotheses come from the identified paper, while the notebook gives only the motivating outline.')
correction('P001419','product formula domain',r'a\in\mathbb Q',r'a\in\mathbb Q^\times','Scan and both transcriptions omit the nonzero condition; the formula fails for zero.')
correction('P001419','gamma ratio, equation (3)',r'\pi^{-s+1}',r'\pi^{1/2-s}','The scan visibly has -s+1. Dividing the two sides of equation (2), also confirmed against DLMF25.4, gives 1/2-s. Faithful notebook error.')
correction('P001420','adelic product notation',r'SL(n,\mathbb A)\sim SL(n,\mathbb R)\times SL(n,\mathbb Q_2)\times\cdots','Use the restricted product with respect to SL(n,Z_p)','The displayed ordinary product is shorthand; the restricted-product condition is required for adeles. Mathematical completion, not alteration of handwriting.','both','ambiguity')
correction('P001422','Deligne formula',r'\det H^\bullet=\det F_K','An inverse is needed for determinant weights under the stated convention; a full corrected epsilon-line formula needs additional hypotheses','Scan inspected: no inverse is written. A constant local system has weight 2-2g on the left and 2g-2 on the right. Do not present this sign correction as a proved universal replacement.')
